#![cfg(not(target_os = "wasi"))]
//! Regression test for the `Database::backup` / `process_freed_pages` race.
//!
//! Background:
//!   `Database::backup` copies the **persisted file** byte-for-byte via
//!   `read_raw` -> `CachedFile::read_direct`, which bypasses the page cache.
//!   The file therefore contains only the last durable commit -- the primary
//!   slot, transaction id `D`. But the snapshot was pinned with
//!   `begin_read()`, which registers via `get_last_committed_transaction_id`
//!   and so honors `read_from_secondary`. After a non-durable commit that
//!   returns the secondary slot's id `N`, with `N > D`.
//!
//!   The safety invariant for any reader is `registered_id <= walked_tree_id`,
//!   because a durable commit's `process_freed_pages` frees DATA_FREED_TABLE /
//!   SYSTEM_FREED_TABLE entries for all txns `<= oldest_live_read_transaction`.
//!   With `registered = N` and `walked = D`, the invariant is violated and
//!   entries for `(D, N]` -- persisted pages still reachable from the tree at
//!   `D` -- become eligible for reclamation.
//!
//!   It takes two durable commits inside the copy window. The first is
//!   protected because `register_non_durable_commit` also holds a read hold on
//!   the durable ancestor `D`; that hold is only released by
//!   `clear_pending_non_durable_commits()`, which runs inside `durable_commit`
//!   after `mem.commit()`. The second durable commit then sees the backup's
//!   hold at `N` as the oldest, computes `free_until = N + 1`, and frees the
//!   `(D, N]` entries. The buddy allocator hands those pages straight back out,
//!   the commit fsyncs new content into the same file offsets, and the
//!   still-running copy loop reads the new bytes.
//!
//!   Result: `backup()` returns `Ok(())` and produces a file whose header names
//!   durable txn `D` but whose interior pages are a mix of `D` and a later
//!   commit -- interior B-tree nodes pointing at unrelated data. The failure is
//!   silent until someone tries to restore.
//!
//! This test exercises that exact pattern: a writer alternates non-durable and
//! durable commits with churn (insert + delete) so DATA_FREED_TABLE accumulates
//! entries spanning `(D, N]`, while a backup thread repeatedly copies the
//! database and verifies each copy with `verify_backup(VerifyLevel::Full)`.
//! Without the fix the copied file fails checksum or structural verification;
//! with the fix every backup must verify clean.

use shodh_redb::{Database, Durability, TableDefinition, VerifyLevel};
use std::sync::Arc;
use std::sync::atomic::{AtomicBool, Ordering};
use std::thread;
use std::time::{Duration, Instant};

const TABLE: TableDefinition<u64, &[u8]> = TableDefinition::new("backup_concurrent");

fn create_tempfile() -> tempfile::NamedTempFile {
    tempfile::NamedTempFile::new().unwrap()
}

#[test]
fn backup_stays_consistent_under_mixed_durability_commits() {
    let tmpfile = create_tempfile();
    let db = Arc::new(Database::create(tmpfile.path()).unwrap());

    // Seed enough data that a full-file copy takes long enough for several
    // commits to land inside the copy window.
    {
        let txn = db.begin_write().unwrap();
        {
            let mut table = txn.open_table(TABLE).unwrap();
            let value = vec![0xABu8; 1024];
            for i in 0..8_000u64 {
                table.insert(i, value.as_slice()).unwrap();
            }
        }
        txn.commit().unwrap();
    }

    let stop = Arc::new(AtomicBool::new(false));

    // Writer thread: alternate non-durable and durable commits with churn.
    // Each iteration:
    //   - a non-durable commit overwriting a band of keys, which sets
    //     `read_from_secondary = true` and advances last_committed to `N`
    //     while the primary slot stays at `D`,
    //   - a non-durable commit deleting part of that band, populating
    //     DATA_FREED_TABLE with entries for txns in `(D, N]` that list
    //     persisted pages reachable from the tree at `D`,
    //   - two durable commits, which is what it takes to drop the
    //     durable-ancestor hold and then free the `(D, N]` entries.
    let writer_db = db.clone();
    let writer_stop = stop.clone();
    let writer = thread::spawn(move || {
        let mut iter: u64 = 0;
        let large = vec![0xCDu8; 1024];
        while !writer_stop.load(Ordering::Relaxed) {
            let band = (iter % 16) * 256;

            // Non-durable overwrite -- keeps read_from_secondary set.
            {
                let mut txn = writer_db.begin_write().unwrap();
                txn.set_durability(Durability::None).unwrap();
                {
                    let mut table = txn.open_table(TABLE).unwrap();
                    for k in band..band + 256 {
                        table.insert(k, large.as_slice()).unwrap();
                    }
                }
                txn.commit().unwrap();
            }

            // Non-durable delete -- creates DATA_FREED_TABLE entries listing
            // persisted pages that are still reachable from the primary root.
            {
                let mut txn = writer_db.begin_write().unwrap();
                txn.set_durability(Durability::None).unwrap();
                {
                    let mut table = txn.open_table(TABLE).unwrap();
                    for k in band..band + 128 {
                        table.remove(&k).unwrap();
                    }
                }
                txn.commit().unwrap();
            }

            // Two durable commits: the first clears the pending non-durable
            // ancestor holds, the second frees the (D, N] entries.
            for step in 0..2u64 {
                let other_band = ((iter + 7 + step) % 16) * 256;
                let txn = writer_db.begin_write().unwrap();
                {
                    let mut table = txn.open_table(TABLE).unwrap();
                    for k in other_band..other_band + 64 {
                        table.insert(k, large.as_slice()).unwrap();
                    }
                }
                txn.commit().unwrap();
            }

            iter += 1;
        }
    });

    // Backup thread: copy the database, then verify the copy. Without the fix
    // the copy contains pages reclaimed and rewritten mid-copy, so full
    // verification reports corrupt pages or a broken structure.
    let backup_db = db.clone();
    let backup_stop = stop.clone();
    let backup = thread::spawn(move || -> Result<(), String> {
        let start = Instant::now();
        let mut runs: u64 = 0;
        while runs < 20 && start.elapsed() < Duration::from_secs(60) {
            let dest = create_tempfile();
            backup_db
                .backup(dest.path())
                .map_err(|e| format!("backup returned error: {e:?}"))?;

            let report = Database::verify_backup(dest.path(), VerifyLevel::Full)
                .map_err(|e| format!("verify_backup returned error on run {runs}: {e:?}"))?;
            if !report.valid {
                return Err(format!(
                    "backup produced a corrupt file on run {runs}: {} of {} pages corrupt, \
                     header_valid={}, structural_valid={:?}, details={:?}",
                    report.pages_corrupt,
                    report.pages_checked,
                    report.header_valid,
                    report.structural_valid,
                    report.corrupt_details
                ));
            }
            runs += 1;
        }
        backup_stop.store(true, Ordering::Relaxed);
        Ok(())
    });

    let backup_result = backup.join().expect("backup thread panicked");
    stop.store(true, Ordering::Relaxed);
    writer.join().expect("writer thread panicked");

    backup_result.expect("backup must produce a verifiable file under concurrent commits");
}

use crate::compat::HashMap;
#[cfg(not(feature = "std"))]
use crate::compat::Mutex;
use crate::error::StorageError;
use crate::tree_store::TransactionalMemory;
use crate::{Key, Result, Savepoint, TypeName, Value};
use alloc::collections::{BTreeMap, BTreeSet};
use alloc::format;
use core::cmp::Ordering;
use core::mem;
use core::mem::size_of;
#[cfg(feature = "logging")]
use log::debug;
#[cfg(feature = "std")]
use std::sync::{Condvar, Mutex};

#[derive(Copy, Clone, Hash, Ord, PartialOrd, Eq, PartialEq, Debug)]
pub(crate) struct TransactionId(u64);

impl TransactionId {
    pub(crate) fn new(value: u64) -> TransactionId {
        Self(value)
    }

    pub(crate) fn raw_id(self) -> u64 {
        self.0
    }

    pub(crate) fn next(self) -> Result<TransactionId> {
        let value = self.0.checked_add(1).ok_or(StorageError::OutOfSpace)?;
        Ok(TransactionId(value))
    }

    pub(crate) fn increment(&mut self) -> Result<TransactionId> {
        let next = self.next()?;
        *self = next;
        Ok(next)
    }
}

#[derive(Copy, Clone, Ord, PartialOrd, Eq, PartialEq, Hash, Debug)]
pub(crate) struct SavepointId(pub u64);

impl SavepointId {
    pub(crate) fn next(self) -> Result<SavepointId> {
        let value = self.0.checked_add(1).ok_or(StorageError::OutOfSpace)?;
        Ok(SavepointId(value))
    }
}

impl Value for SavepointId {
    type SelfType<'a> = SavepointId;
    type AsBytes<'a> = [u8; size_of::<u64>()];

    fn fixed_width() -> Option<usize> {
        Some(size_of::<u64>())
    }

    #[allow(clippy::big_endian_bytes)]
    fn from_bytes<'a>(data: &'a [u8]) -> Self::SelfType<'a>
    where
        Self: 'a,
    {
        if data.len() < size_of::<u64>() {
            return SavepointId(0);
        }
        SavepointId(u64::from_be_bytes([
            data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7],
        ]))
    }

    #[allow(clippy::big_endian_bytes)]
    fn as_bytes<'a, 'b: 'a>(value: &'a Self::SelfType<'b>) -> Self::AsBytes<'a>
    where
        Self: 'b,
    {
        value.0.to_be_bytes()
    }

    fn type_name() -> TypeName {
        TypeName::internal("redb::SavepointId")
    }
}

impl Key for SavepointId {
    fn compare(data1: &[u8], data2: &[u8]) -> Ordering {
        // Big-endian serialization means raw byte comparison is correct.
        data1[..size_of::<u64>()].cmp(&data2[..size_of::<u64>()])
    }
}

struct State {
    next_savepoint_id: SavepointId,
    // reference count of read transactions per transaction id
    live_read_transactions: BTreeMap<TransactionId, u64>,
    next_transaction_id: TransactionId,
    live_write_transaction: Option<TransactionId>,
    valid_savepoints: BTreeMap<SavepointId, TransactionId>,
    // Non-durable commits that are still in-memory, and waiting for a durable commit to get flushed
    // We need to make sure that the freed-table does not get processed for these, since they are not durable yet
    // Therefore, we hold a read transaction on their nearest durable ancestor
    //
    // Maps non-durable transaction id -> durable ancestor
    pending_non_durable_commits: HashMap<TransactionId, TransactionId>,
    // Non-durable commits which have NOT been processed in the freed table
    unprocessed_freed_non_durable_commits: BTreeSet<TransactionId>,
}

pub(crate) struct TransactionTracker {
    state: Mutex<State>,
    #[cfg(feature = "std")]
    live_write_transaction_available: Condvar,
}

impl TransactionTracker {
    pub(crate) fn new(next_transaction_id: TransactionId) -> Self {
        Self {
            state: Mutex::new(State {
                next_savepoint_id: SavepointId(0),
                live_read_transactions: Default::default(),
                next_transaction_id,
                live_write_transaction: None,
                valid_savepoints: Default::default(),
                pending_non_durable_commits: Default::default(),
                unprocessed_freed_non_durable_commits: Default::default(),
            }),
            #[cfg(feature = "std")]
            live_write_transaction_available: Condvar::new(),
        }
    }

    #[cfg(feature = "std")]
    pub(crate) fn start_write_transaction(&self) -> Result<TransactionId> {
        let mut state = self.state.lock()?;
        while state.live_write_transaction.is_some() {
            state = self.live_write_transaction_available.wait(state)?;
        }
        if state.live_write_transaction.is_some() {
            return Err(StorageError::Internal(
                "Write transaction still active after condvar wait".into(),
            ));
        }
        let transaction_id = state.next_transaction_id.increment()?;
        #[cfg(feature = "logging")]
        debug!("Beginning write transaction id={transaction_id:?}");
        state.live_write_transaction = Some(transaction_id);

        Ok(transaction_id)
    }

    /// NOTE (`no_std`): `spin::Mutex::lock()` does not detect poisoning, so if a
    /// thread panics while holding the lock the mutex silently continues with
    /// potentially inconsistent inner state. This is an accepted limitation of
    /// the `no_std` spin-lock implementation -- callers that require strict
    /// consistency guarantees should use the `std` feature.
    #[cfg(not(feature = "std"))]
    pub(crate) fn start_write_transaction(&self) -> Result<TransactionId> {
        const MAX_SPIN_RETRIES: u32 = 1000;
        let mut retries: u32 = 0;
        let mut backoff: u32 = 1;

        loop {
            let mut state = self.state.lock();
            if state.live_write_transaction.is_none() {
                let transaction_id = state.next_transaction_id.increment()?;
                #[cfg(feature = "logging")]
                debug!("Beginning write transaction id={transaction_id:?}");
                state.live_write_transaction = Some(transaction_id);
                return Ok(transaction_id);
            }
            drop(state);

            retries += 1;
            if retries >= MAX_SPIN_RETRIES {
                return Err(StorageError::LockTimeout(
                    "Timed out waiting for write transaction lock after 1000 spin iterations"
                        .into(),
                ));
            }

            for _ in 0..backoff {
                core::hint::spin_loop();
            }
            backoff = backoff.saturating_mul(2).min(64);
        }
    }

    #[cfg(feature = "std")]
    pub(crate) fn end_write_transaction(&self, id: TransactionId) -> Result {
        let mut state = self.state.lock()?;
        match state.live_write_transaction {
            Some(active_id) if active_id == id => {
                state.live_write_transaction = None;
                self.live_write_transaction_available.notify_one();
                Ok(())
            }
            Some(active_id) => Err(StorageError::Internal(format!(
                "end_write_transaction called with id {id:?}, but active transaction is {active_id:?}"
            ))),
            None => Err(StorageError::Internal(format!(
                "end_write_transaction called with id {id:?}, but no write transaction is active"
            ))),
        }
    }

    /// NOTE (`no_std`): see `start_write_transaction` for spin-lock poisoning caveat.
    #[cfg(not(feature = "std"))]
    pub(crate) fn end_write_transaction(&self, id: TransactionId) -> Result {
        let mut state = self.state.lock();
        match state.live_write_transaction {
            Some(active_id) if active_id == id => {
                state.live_write_transaction = None;
                Ok(())
            }
            Some(active_id) => Err(StorageError::Internal(format!(
                "end_write_transaction called with id {id:?}, but active transaction is {active_id:?}"
            ))),
            None => Err(StorageError::Internal(format!(
                "end_write_transaction called with id {id:?}, but no write transaction is active"
            ))),
        }
    }

    pub(crate) fn clear_pending_non_durable_commits(&self) -> Result {
        #[cfg(feature = "std")]
        let mut state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let mut state = self.state.lock();
        let ids = mem::take(&mut state.pending_non_durable_commits);
        for (_, durable_ancestor) in ids {
            if let Some(ref_count) = state.live_read_transactions.get_mut(&durable_ancestor) {
                *ref_count -= 1;
                if *ref_count == 0 {
                    state.live_read_transactions.remove(&durable_ancestor);
                }
            }
        }
        Ok(())
    }

    pub(crate) fn is_unprocessed_non_durable_commit(&self, id: TransactionId) -> Result<bool> {
        #[cfg(feature = "std")]
        let state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let state = self.state.lock();
        Ok(state.unprocessed_freed_non_durable_commits.contains(&id))
    }

    pub(crate) fn mark_non_durable_commit_processed(&self, id: TransactionId) -> Result {
        #[cfg(feature = "std")]
        let mut state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let mut state = self.state.lock();
        state.unprocessed_freed_non_durable_commits.remove(&id);
        Ok(())
    }

    pub(crate) fn oldest_unprocessed_non_durable_commit(&self) -> Result<Option<TransactionId>> {
        #[cfg(feature = "std")]
        let state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let state = self.state.lock();
        Ok(state
            .unprocessed_freed_non_durable_commits
            .iter()
            .next()
            .copied())
    }

    /// Maximum number of non-durable commits that can be pending before a
    /// durable commit is required. Prevents unbounded memory growth.
    const MAX_PENDING_NON_DURABLE: usize = 10_000;

    pub(crate) fn register_non_durable_commit(
        &self,
        id: TransactionId,
        durable_ancestor: TransactionId,
    ) -> Result {
        #[cfg(feature = "std")]
        let mut state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let mut state = self.state.lock();
        if state.pending_non_durable_commits.len() >= Self::MAX_PENDING_NON_DURABLE {
            return Err(StorageError::Internal(alloc::format!(
                "too many pending non-durable commits (limit: {}); a durable commit is required",
                Self::MAX_PENDING_NON_DURABLE
            )));
        }
        state
            .live_read_transactions
            .entry(durable_ancestor)
            .and_modify(|x| *x += 1)
            .or_insert(1);
        state
            .pending_non_durable_commits
            .insert(id, durable_ancestor);
        state.unprocessed_freed_non_durable_commits.insert(id);
        Ok(())
    }

    pub(crate) fn restore_savepoint_counter_state(&self, next_savepoint: SavepointId) -> Result {
        #[cfg(feature = "std")]
        let mut state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let mut state = self.state.lock();
        if !state.valid_savepoints.is_empty() {
            return Err(StorageError::Internal(
                "restore_savepoint_counter_state called with active savepoints".into(),
            ));
        }
        state.next_savepoint_id = next_savepoint;
        Ok(())
    }

    pub(crate) fn register_persistent_savepoint(&self, savepoint: &Savepoint) -> Result {
        #[cfg(feature = "std")]
        let mut state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let mut state = self.state.lock();
        state
            .live_read_transactions
            .entry(savepoint.get_transaction_id())
            .and_modify(|x| *x += 1)
            .or_insert(1);
        state
            .valid_savepoints
            .insert(savepoint.get_id(), savepoint.get_transaction_id());
        Ok(())
    }

    pub(crate) fn register_read_transaction(
        &self,
        mem: &TransactionalMemory,
    ) -> Result<TransactionId> {
        #[cfg(feature = "std")]
        let mut state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let mut state = self.state.lock();
        let id = mem.get_last_committed_transaction_id()?;
        state
            .live_read_transactions
            .entry(id)
            .and_modify(|x| *x += 1)
            .or_insert(1);

        Ok(id)
    }

    /// Register a read hold pegged to the last **durable** transaction id
    /// (the primary slot's id), regardless of whether `read_from_secondary`
    /// is currently set.
    ///
    /// This is the correct registration when the caller intends to read the
    /// **persisted** roots (`get_persisted_data_root` / `get_persisted_system_root`).
    /// Using `register_read_transaction` in that case creates an id/root
    /// mismatch: the registered id may be the secondary (non-durable) txn id
    /// `N`, but the persisted root being walked corresponds to the older
    /// primary id `N-K`. A concurrent durable commit's `process_freed_pages`
    /// then frees pages reachable from the primary root (entries in
    /// `DATA_FREED_TABLE` / `SYSTEM_FREED_TABLE` for txns in `N-K+1 ..= N`),
    /// causing the reader to follow pointers into reclaimed pages.
    ///
    /// Pegging the registration to the durable id ensures
    /// `oldest_live_read_transaction <= durable_id`, so `process_freed_pages`
    /// only frees entries with txn `<= durable_id` -- which by construction
    /// are not reachable from the durable root being walked.
    #[cfg(feature = "std")]
    pub(crate) fn register_durable_read_transaction(
        &self,
        mem: &TransactionalMemory,
    ) -> Result<TransactionId> {
        let mut state = self.state.lock()?;
        let id = mem.get_last_durable_transaction_id()?;
        state
            .live_read_transactions
            .entry(id)
            .and_modify(|x| *x += 1)
            .or_insert(1);

        Ok(id)
    }

    /// Atomically attempt to extend the read hold on an existing historical
    /// snapshot. Returns `true` if `transaction_id` was already present in
    /// `live_read_transactions` (i.e. the snapshot's `register_history_hold`
    /// is still alive) and the count was incremented; returns `false` if the
    /// snapshot has already been evicted from the retention window.
    ///
    /// This is the correct registration for time-travel reads
    /// (`Database::begin_read_at`, `Database::begin_read_at_time`): the
    /// caller looks up a historical snapshot in the system history table,
    /// then must extend the snapshot's hold before walking pages reachable
    /// from its `user_root`. Without this, retention pruning could
    /// `deallocate_history_hold(transaction_id)` between the lookup and the
    /// read, allowing `oldest_live_read_transaction` to advance past
    /// `transaction_id` and `process_freed_pages` to reclaim pages
    /// reachable from the historical user tree -- the same id/root mismatch
    /// class fixed for `verify_integrity` and the integrity scanner.
    ///
    /// The check-and-increment is atomic under the tracker lock, so it
    /// serialises correctly with retention pruning's
    /// `deallocate_history_hold` call.
    pub(crate) fn try_register_historical_read_transaction(
        &self,
        transaction_id: TransactionId,
    ) -> Result<bool> {
        #[cfg(feature = "std")]
        let mut state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let mut state = self.state.lock();
        if let Some(ref_count) = state.live_read_transactions.get_mut(&transaction_id) {
            *ref_count += 1;
            Ok(true)
        } else {
            Ok(false)
        }
    }

    pub(crate) fn deallocate_read_transaction(&self, id: TransactionId) -> Result {
        #[cfg(feature = "std")]
        let mut state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let mut state = self.state.lock();
        if let Some(ref_count) = state.live_read_transactions.get_mut(&id) {
            *ref_count -= 1;
            if *ref_count == 0 {
                state.live_read_transactions.remove(&id);
            }
        }
        Ok(())
    }

    pub(crate) fn any_savepoint_exists(&self) -> Result<bool> {
        #[cfg(feature = "std")]
        let state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let state = self.state.lock();
        Ok(!state.valid_savepoints.is_empty())
    }

    pub(crate) fn allocate_savepoint(&self, transaction_id: TransactionId) -> Result<SavepointId> {
        #[cfg(feature = "std")]
        let mut state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let mut state = self.state.lock();
        let id = state.next_savepoint_id.next()?;
        state.next_savepoint_id = id;
        state.valid_savepoints.insert(id, transaction_id);
        Ok(id)
    }

    // Deallocates the given savepoint and its matching reference count on the transaction
    pub(crate) fn deallocate_savepoint(
        &self,
        savepoint: SavepointId,
        transaction: TransactionId,
    ) -> Result {
        {
            #[cfg(feature = "std")]
            let mut state = self.state.lock()?;
            #[cfg(not(feature = "std"))]
            let mut state = self.state.lock();
            state.valid_savepoints.remove(&savepoint);
        }
        self.deallocate_read_transaction(transaction)
    }

    pub(crate) fn is_valid_savepoint(&self, id: SavepointId) -> Result<bool> {
        #[cfg(feature = "std")]
        let state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let state = self.state.lock();
        Ok(state.valid_savepoints.contains_key(&id))
    }

    pub(crate) fn invalidate_savepoints_after(&self, id: SavepointId) -> Result {
        #[cfg(feature = "std")]
        let mut state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let mut state = self.state.lock();
        state.valid_savepoints.retain(|x, _| *x <= id);
        Ok(())
    }

    pub(crate) fn oldest_savepoint(&self) -> Result<Option<(SavepointId, TransactionId)>> {
        #[cfg(feature = "std")]
        let state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let state = self.state.lock();
        Ok(state
            .valid_savepoints
            .first_key_value()
            .map(|x| (*x.0, *x.1)))
    }

    pub(crate) fn oldest_live_read_transaction(&self) -> Result<Option<TransactionId>> {
        #[cfg(feature = "std")]
        let state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let state = self.state.lock();
        Ok(state.live_read_transactions.keys().next().copied())
    }

    pub(crate) fn register_history_hold(&self, transaction_id: TransactionId) -> Result {
        #[cfg(feature = "std")]
        let mut state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let mut state = self.state.lock();
        state
            .live_read_transactions
            .entry(transaction_id)
            .and_modify(|x| *x += 1)
            .or_insert(1);
        Ok(())
    }

    pub(crate) fn deallocate_history_hold(&self, transaction_id: TransactionId) -> Result {
        #[cfg(feature = "std")]
        let mut state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let mut state = self.state.lock();
        if let Some(ref_count) = state.live_read_transactions.get_mut(&transaction_id) {
            *ref_count -= 1;
            if *ref_count == 0 {
                state.live_read_transactions.remove(&transaction_id);
            }
        }
        Ok(())
    }

    // Returns the oldest external read transaction -- one not solely held by
    // durable-ancestor registrations from pending non-durable commits. Used to
    // guard non-durable page freeing: if real readers exist, their snapshots
    // must not be invalidated by freeing pages they might traverse.
    pub(crate) fn oldest_live_read_transaction_excluding_nondurable(
        &self,
    ) -> Result<Option<TransactionId>> {
        #[cfg(feature = "std")]
        let state = self.state.lock()?;
        #[cfg(not(feature = "std"))]
        let state = self.state.lock();

        // Count durable-ancestor holds from non-durable commits.
        let mut ancestor_holds: BTreeMap<TransactionId, u64> = BTreeMap::new();
        for ancestor in state.pending_non_durable_commits.values() {
            *ancestor_holds.entry(*ancestor).or_insert(0) += 1;
        }

        for (id, refcount) in &state.live_read_transactions {
            let nondurable_holds = ancestor_holds.get(id).copied().unwrap_or(0);
            if *refcount > nondurable_holds {
                return Ok(Some(*id));
            }
        }
        Ok(None)
    }
}

use crate::error::StorageError;
use crate::types::{Key, TypeName, Value};
use alloc::format;
use alloc::string::String;
use alloc::vec::Vec;
use core::cmp::Ordering;
use core::fmt;

// ---------------------------------------------------------------------------
// CdcConfig
// ---------------------------------------------------------------------------

/// Configuration for Change Data Capture.
///
/// Set on the database [`Builder`](crate::Builder) via `set_cdc()`.
/// When disabled (the default), CDC has zero overhead.
#[derive(Debug, Clone, Default)]
pub struct CdcConfig {
    /// Whether CDC is enabled.
    pub enabled: bool,
    /// Maximum number of committed transactions to retain in the CDC log.
    /// 0 means unlimited (entries are never pruned automatically).
    pub retention_max_txns: u64,
}

// ---------------------------------------------------------------------------
// ChangeOp
// ---------------------------------------------------------------------------

/// The type of mutation captured by a CDC event.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum ChangeOp {
    /// A new key was inserted (no previous value existed).
    Insert = 0,
    /// An existing key was overwritten with a new value.
    Update = 1,
    /// A key was removed.
    Delete = 2,
    /// The on-disk record could not be deserialized. Consumers should skip
    /// records with this variant -- they do not represent real mutations.
    Corrupted = 255,
}

impl ChangeOp {
    fn from_u8(v: u8) -> Result<Self, StorageError> {
        match v {
            0 => Ok(Self::Insert),
            1 => Ok(Self::Update),
            2 => Ok(Self::Delete),
            other => Err(StorageError::format_error(format!(
                "invalid ChangeOp discriminant byte: {other}"
            ))),
        }
    }
}

// ---------------------------------------------------------------------------
// CdcEvent -- in-memory accumulator (not persisted directly)
// ---------------------------------------------------------------------------

/// In-memory change event accumulated during a write transaction.
///
/// These are flushed to the CDC system table on commit.
pub(crate) struct CdcEvent {
    pub table_name: String,
    pub op: ChangeOp,
    pub key: Vec<u8>,
    pub new_value: Option<Vec<u8>>,
    pub old_value: Option<Vec<u8>>,
}

// ---------------------------------------------------------------------------
// CdcKey -- system table key (fixed-width, 12 bytes)
// ---------------------------------------------------------------------------

/// Key for the CDC log system table.
///
/// Encoded as 12 bytes big-endian: `[transaction_id: u64][sequence: u32]`.
/// Big-endian ensures lexicographic byte order matches numeric order.
#[derive(Debug, Clone, Copy, PartialEq, Eq, Hash)]
pub struct CdcKey {
    pub transaction_id: u64,
    pub sequence: u32,
}

impl CdcKey {
    pub const SERIALIZED_SIZE: usize = 12;

    pub fn new(transaction_id: u64, sequence: u32) -> Self {
        Self {
            transaction_id,
            sequence,
        }
    }

    #[allow(clippy::big_endian_bytes)]
    pub(crate) fn to_be_bytes(self) -> [u8; Self::SERIALIZED_SIZE] {
        let mut buf = [0u8; Self::SERIALIZED_SIZE];
        buf[..8].copy_from_slice(&self.transaction_id.to_be_bytes());
        buf[8..12].copy_from_slice(&self.sequence.to_be_bytes());
        buf
    }

    #[allow(clippy::big_endian_bytes)]
    pub(crate) fn from_be_bytes(data: &[u8]) -> Self {
        debug_assert!(
            data.len() >= Self::SERIALIZED_SIZE,
            "CdcKey::from_be_bytes: truncated data ({} < {})",
            data.len(),
            Self::SERIALIZED_SIZE,
        );
        if data.len() < Self::SERIALIZED_SIZE {
            return Self {
                transaction_id: 0,
                sequence: 0,
            };
        }
        let transaction_id = u64::from_be_bytes([
            data[0], data[1], data[2], data[3], data[4], data[5], data[6], data[7],
        ]);
        let sequence = u32::from_be_bytes([data[8], data[9], data[10], data[11]]);
        Self {
            transaction_id,
            sequence,
        }
    }
}

impl PartialOrd for CdcKey {
    fn partial_cmp(&self, other: &Self) -> Option<Ordering> {
        Some(self.cmp(other))
    }
}

impl Ord for CdcKey {
    fn cmp(&self, other: &Self) -> Ordering {
        self.transaction_id
            .cmp(&other.transaction_id)
            .then(self.sequence.cmp(&other.sequence))
    }
}

impl Value for CdcKey {
    type SelfType<'a>
        = CdcKey
    where
        Self: 'a;
    type AsBytes<'a>
        = [u8; CdcKey::SERIALIZED_SIZE]
    where
        Self: 'a;

    fn fixed_width() -> Option<usize> {
        Some(Self::SERIALIZED_SIZE)
    }

    fn from_bytes<'a>(data: &'a [u8]) -> Self::SelfType<'a>
    where
        Self: 'a,
    {
        Self::from_be_bytes(data)
    }

    fn as_bytes<'a, 'b: 'a>(value: &'a Self::SelfType<'b>) -> Self::AsBytes<'a>
    where
        Self: 'b,
    {
        value.to_be_bytes()
    }

    fn type_name() -> TypeName {
        TypeName::internal("redb::cdc::CdcKey")
    }
}

impl Key for CdcKey {
    fn compare(data1: &[u8], data2: &[u8]) -> Ordering {
        // Big-endian serialization means raw byte comparison is correct.
        let len = Self::SERIALIZED_SIZE.min(data1.len()).min(data2.len());
        data1[..len]
            .cmp(&data2[..len])
            .then_with(|| data1.len().cmp(&data2.len()))
    }
}

// ---------------------------------------------------------------------------
// CdcRecord -- system table value (variable-width)
// ---------------------------------------------------------------------------

const NONE_SENTINEL: u32 = u32::MAX;

/// Magic byte identifying a versioned CDC record. Chosen to be > 2 (outside
/// the valid `ChangeOp` discriminant range) so that legacy v0 records --
/// which start directly with an op byte (0, 1, or 2) -- can be distinguished.
const CDC_FORMAT_MAGIC: u8 = 0xCD;

/// Current CDC record format version.
const CDC_FORMAT_VERSION: u8 = 1;

/// Serialized CDC change record stored in the system table.
///
/// Binary layout (v1, current):
/// ```text
/// [CDC_FORMAT_MAGIC: u8 = 0xCD][version: u8 = 1]
/// [op: u8]
/// [table_name_len: u16 LE][table_name: N bytes]
/// [key_len: u32 LE][key: N bytes]
/// [new_val_len: u32 LE][new_val: N bytes]    -- 0xFFFFFFFF if None
/// [old_val_len: u32 LE][old_val: N bytes]    -- 0xFFFFFFFF if None
/// ```
///
/// Legacy (v0) records omit the magic+version header and start directly with
/// the `op` byte. The deserializer distinguishes the two: if the first byte
/// equals `CDC_FORMAT_MAGIC` it is a versioned record, otherwise legacy.
#[derive(Clone)]
pub struct CdcRecord {
    pub op: ChangeOp,
    pub table_name: String,
    pub key: Vec<u8>,
    pub new_value: Option<Vec<u8>>,
    pub old_value: Option<Vec<u8>>,
}

impl fmt::Debug for CdcRecord {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        f.debug_struct("CdcRecord")
            .field("op", &self.op)
            .field("table_name", &self.table_name)
            .field("key", &self.key)
            .field("new_value", &self.new_value)
            .field("old_value", &self.old_value)
            .finish()
    }
}

impl CdcRecord {
    pub(crate) fn from_event(event: &CdcEvent) -> Result<Self, StorageError> {
        if u16::try_from(event.table_name.len()).is_err() {
            return Err(StorageError::format_error(format!(
                "CDC table_name exceeds u16::MAX bytes ({})",
                event.table_name.len()
            )));
        }
        if event.key.len() >= NONE_SENTINEL as usize {
            return Err(StorageError::format_error(format!(
                "CDC key exceeds maximum serializable length ({})",
                event.key.len()
            )));
        }
        if event
            .new_value
            .as_ref()
            .is_some_and(|v| v.len() >= NONE_SENTINEL as usize)
        {
            return Err(StorageError::format_error(format!(
                "CDC new_value exceeds maximum serializable length ({})",
                event.new_value.as_ref().unwrap().len()
            )));
        }
        if event
            .old_value
            .as_ref()
            .is_some_and(|v| v.len() >= NONE_SENTINEL as usize)
        {
            return Err(StorageError::format_error(format!(
                "CDC old_value exceeds maximum serializable length ({})",
                event.old_value.as_ref().unwrap().len()
            )));
        }
        Ok(Self {
            op: event.op,
            table_name: event.table_name.clone(),
            key: event.key.clone(),
            new_value: event.new_value.clone(),
            old_value: event.old_value.clone(),
        })
    }

    pub(crate) fn serialized_size(&self) -> usize {
        2 // magic + version
        + 1 // op
        + 2 + self.table_name.len() // table_name_len + table_name
        + 4 + self.key.len() // key_len + key
        + 4 + self.new_value.as_ref().map_or(0, Vec::len) // new_val_len + new_val
        + 4 + self.old_value.as_ref().map_or(0, Vec::len) // old_val_len + old_val
    }

    pub fn serialize(&self) -> Vec<u8> {
        let mut buf = Vec::with_capacity(self.serialized_size());

        buf.push(CDC_FORMAT_MAGIC);
        buf.push(CDC_FORMAT_VERSION);
        buf.push(self.op as u8);

        let name_len = u16::try_from(self.table_name.len()).unwrap_or(u16::MAX);
        buf.extend_from_slice(&name_len.to_le_bytes());
        buf.extend_from_slice(&self.table_name.as_bytes()[..usize::from(name_len)]);

        let key_len = u32::try_from(self.key.len()).unwrap_or(NONE_SENTINEL - 1);
        buf.extend_from_slice(&key_len.to_le_bytes());
        buf.extend_from_slice(&self.key[..key_len as usize]);

        match &self.new_value {
            Some(v) => {
                let len = u32::try_from(v.len()).unwrap_or(NONE_SENTINEL - 1);
                buf.extend_from_slice(&len.to_le_bytes());
                buf.extend_from_slice(&v[..len as usize]);
            }
            None => {
                buf.extend_from_slice(&NONE_SENTINEL.to_le_bytes());
            }
        }

        match &self.old_value {
            Some(v) => {
                let len = u32::try_from(v.len()).unwrap_or(NONE_SENTINEL - 1);
                buf.extend_from_slice(&len.to_le_bytes());
                buf.extend_from_slice(&v[..len as usize]);
            }
            None => {
                buf.extend_from_slice(&NONE_SENTINEL.to_le_bytes());
            }
        }

        buf
    }

    pub fn deserialize(data: &[u8]) -> Result<Self, StorageError> {
        let mut pos = 0;

        if data.is_empty() {
            return Err(StorageError::format_error("CDC record is empty"));
        }

        // Detect format: if first byte is the magic, this is a versioned
        // record. Otherwise it is a legacy v0 record whose first byte is the
        // op discriminant (0, 1, or 2).
        if data[pos] == CDC_FORMAT_MAGIC {
            pos += 1; // skip magic
            if pos >= data.len() {
                return Err(StorageError::format_error(
                    "CDC record truncated at version byte",
                ));
            }
            let version = data[pos];
            pos += 1;
            if version != CDC_FORMAT_VERSION {
                return Err(StorageError::format_error(format!(
                    "unsupported CDC record version {version} (expected {CDC_FORMAT_VERSION})"
                )));
            }
        }

        if pos >= data.len() {
            return Err(StorageError::format_error(
                "CDC record truncated at op byte",
            ));
        }
        let op = ChangeOp::from_u8(data[pos])?;
        pos += 1;

        if pos + 2 > data.len() {
            return Err(StorageError::format_error(
                "CDC record truncated at table name length",
            ));
        }
        let name_len = u16::from_le_bytes(data[pos..pos + 2].try_into().map_err(|_| {
            StorageError::format_error("CDC record: invalid table name length bytes")
        })?);
        pos += 2;
        if pos
            .checked_add(usize::from(name_len))
            .is_none_or(|end| end > data.len())
        {
            return Err(StorageError::format_error(
                "CDC record truncated at table name",
            ));
        }
        let table_name =
            String::from_utf8_lossy(&data[pos..pos + usize::from(name_len)]).into_owned();
        pos += usize::from(name_len);

        if pos + 4 > data.len() {
            return Err(StorageError::format_error(
                "CDC record truncated at key length",
            ));
        }
        let key_len = u32::from_le_bytes(
            data[pos..pos + 4]
                .try_into()
                .map_err(|_| StorageError::format_error("CDC record: invalid key length bytes"))?,
        );
        pos += 4;
        if pos
            .checked_add(key_len as usize)
            .is_none_or(|end| end > data.len())
        {
            return Err(StorageError::format_error(
                "CDC record truncated at key data",
            ));
        }
        let key = data[pos..pos + key_len as usize].to_vec();
        pos += key_len as usize;

        if pos + 4 > data.len() {
            return Err(StorageError::format_error(
                "CDC record truncated at new value length",
            ));
        }
        let new_val_len = u32::from_le_bytes(data[pos..pos + 4].try_into().map_err(|_| {
            StorageError::format_error("CDC record: invalid new value length bytes")
        })?);
        pos += 4;
        let new_value = if new_val_len == NONE_SENTINEL {
            None
        } else {
            if pos
                .checked_add(new_val_len as usize)
                .is_none_or(|end| end > data.len())
            {
                return Err(StorageError::format_error(
                    "CDC record truncated at new value data",
                ));
            }
            let v = data[pos..pos + new_val_len as usize].to_vec();
            pos += new_val_len as usize;
            Some(v)
        };

        if pos + 4 > data.len() {
            return Err(StorageError::format_error(
                "CDC record truncated at old value length",
            ));
        }
        let old_val_len = u32::from_le_bytes(data[pos..pos + 4].try_into().map_err(|_| {
            StorageError::format_error("CDC record: invalid old value length bytes")
        })?);
        pos += 4;
        let old_value = if old_val_len == NONE_SENTINEL {
            None
        } else {
            if pos
                .checked_add(old_val_len as usize)
                .is_none_or(|end| end > data.len())
            {
                return Err(StorageError::format_error(
                    "CDC record truncated at old value data",
                ));
            }
            let v = data[pos..pos + old_val_len as usize].to_vec();
            let _ = pos + old_val_len as usize; // last field
            Some(v)
        };

        Ok(Self {
            op,
            table_name,
            key,
            new_value,
            old_value,
        })
    }
}

impl Value for CdcRecord {
    type SelfType<'a>
        = CdcRecord
    where
        Self: 'a;
    type AsBytes<'a>
        = Vec<u8>
    where
        Self: 'a;

    fn fixed_width() -> Option<usize> {
        None
    }

    fn from_bytes<'a>(data: &'a [u8]) -> Self::SelfType<'a>
    where
        Self: 'a,
    {
        match Self::deserialize(data) {
            Ok(record) => record,
            Err(_) => CdcRecord {
                op: ChangeOp::Corrupted,
                table_name: String::new(),
                key: Vec::new(),
                new_value: None,
                old_value: None,
            },
        }
    }

    fn as_bytes<'a, 'b: 'a>(value: &'a Self::SelfType<'b>) -> Self::AsBytes<'a>
    where
        Self: 'b,
    {
        value.serialize()
    }

    fn type_name() -> TypeName {
        TypeName::internal("redb::cdc::CdcRecord")
    }
}

// ---------------------------------------------------------------------------
// ChangeStream -- public query result type
// ---------------------------------------------------------------------------

/// A single change record from the CDC log, returned by
/// [`ReadTransaction::read_cdc_since()`](crate::ReadTransaction::read_cdc_since).
#[derive(Debug, Clone)]
pub struct ChangeStream {
    /// Transaction that produced this change.
    pub transaction_id: u64,
    /// Sequence number within the transaction (0-based).
    pub sequence: u32,
    /// Type of mutation.
    pub op: ChangeOp,
    /// Name of the table that was modified.
    pub table_name: String,
    /// Serialized key bytes.
    pub key: Vec<u8>,
    /// Serialized new value bytes (`None` for [`ChangeOp::Delete`]).
    pub new_value: Option<Vec<u8>>,
    /// Serialized old value bytes (`None` for [`ChangeOp::Insert`]).
    pub old_value: Option<Vec<u8>>,
}

impl ChangeStream {
    pub(crate) fn from_key_record(key: CdcKey, record: CdcRecord) -> Self {
        Self {
            transaction_id: key.transaction_id,
            sequence: key.sequence,
            op: record.op,
            table_name: record.table_name,
            key: record.key,
            new_value: record.new_value,
            old_value: record.old_value,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A declared length near `u32::MAX` must be reported as a truncated
    /// record, never panic. The bounds checks are written as
    /// `pos.checked_add(len)` because `pos + len` wraps on 32-bit targets
    /// (wasm32 / WASI), which would let the guard pass and push the failure
    /// into the slice index as a panic instead of a `StorageError`.
    #[test]
    fn deserialize_rejects_length_that_would_overflow_pointer_width() {
        // Legacy v0 record: op byte, then u16 table-name length, then name.
        let mut rec = Vec::new();
        rec.push(0u8); // op discriminant
        rec.extend_from_slice(&1u16.to_le_bytes()); // name_len = 1
        rec.push(b't'); // table name
        rec.extend_from_slice(&(u32::MAX - 1).to_le_bytes()); // key_len, absurd
        // No key bytes follow -- the record is truncated.

        let result = CdcRecord::deserialize(&rec);
        assert!(
            result.is_err(),
            "a record declaring a near-u32::MAX key length must be rejected, got {result:?}"
        );
    }

    #[test]
    fn deserialize_rejects_oversized_table_name_length() {
        let mut rec = Vec::new();
        rec.push(0u8); // op discriminant
        rec.extend_from_slice(&u16::MAX.to_le_bytes()); // name_len, absurd
        // No name bytes follow.

        assert!(
            CdcRecord::deserialize(&rec).is_err(),
            "a record declaring a u16::MAX table name length must be rejected"
        );
    }

    #[test]
    fn cdc_key_round_trip() {
        let key = CdcKey::new(42, 7);
        let bytes = key.to_be_bytes();
        let decoded = CdcKey::from_be_bytes(&bytes);
        assert_eq!(key, decoded);
    }

    #[test]
    fn cdc_key_ordering() {
        let a = CdcKey::new(1, 0);
        let b = CdcKey::new(1, 1);
        let c = CdcKey::new(2, 0);
        assert!(a < b);
        assert!(b < c);

        // Big-endian: raw byte comparison matches numeric ordering
        let ab = a.to_be_bytes();
        let bb = b.to_be_bytes();
        let cb = c.to_be_bytes();
        assert_eq!(CdcKey::compare(&ab, &bb), core::cmp::Ordering::Less);
        assert_eq!(CdcKey::compare(&bb, &cb), core::cmp::Ordering::Less);
    }

    #[test]
    fn cdc_key_be_ordering_across_byte_boundary() {
        // Regression: LE encoding caused txn_id=256 to sort before txn_id=1
        let small = CdcKey::new(1, 0);
        let large = CdcKey::new(256, 0);
        let sb = small.to_be_bytes();
        let lb = large.to_be_bytes();
        assert_eq!(CdcKey::compare(&sb, &lb), core::cmp::Ordering::Less);
        // Also verify raw lexicographic order is correct
        assert!(sb < lb);
    }

    #[test]
    fn cdc_record_round_trip_insert() {
        let record = CdcRecord {
            op: ChangeOp::Insert,
            table_name: String::from("my_table"),
            key: vec![1, 2, 3],
            new_value: Some(vec![4, 5, 6]),
            old_value: None,
        };
        let bytes = record.serialize();
        let decoded = CdcRecord::deserialize(&bytes).unwrap();
        assert_eq!(decoded.op, ChangeOp::Insert);
        assert_eq!(decoded.table_name, "my_table");
        assert_eq!(decoded.key, vec![1, 2, 3]);
        assert_eq!(decoded.new_value, Some(vec![4, 5, 6]));
        assert!(decoded.old_value.is_none());
    }

    #[test]
    fn cdc_record_round_trip_update() {
        let record = CdcRecord {
            op: ChangeOp::Update,
            table_name: String::from("t"),
            key: vec![10],
            new_value: Some(vec![20]),
            old_value: Some(vec![30]),
        };
        let bytes = record.serialize();
        let decoded = CdcRecord::deserialize(&bytes).unwrap();
        assert_eq!(decoded.op, ChangeOp::Update);
        assert_eq!(decoded.new_value, Some(vec![20]));
        assert_eq!(decoded.old_value, Some(vec![30]));
    }

    #[test]
    fn cdc_record_round_trip_delete() {
        let record = CdcRecord {
            op: ChangeOp::Delete,
            table_name: String::from("x"),
            key: vec![99],
            new_value: None,
            old_value: Some(vec![100]),
        };
        let bytes = record.serialize();
        let decoded = CdcRecord::deserialize(&bytes).unwrap();
        assert_eq!(decoded.op, ChangeOp::Delete);
        assert!(decoded.new_value.is_none());
        assert_eq!(decoded.old_value, Some(vec![100]));
    }

    #[test]
    fn cdc_record_empty_values() {
        let record = CdcRecord {
            op: ChangeOp::Insert,
            table_name: String::new(),
            key: vec![],
            new_value: Some(vec![]),
            old_value: None,
        };
        let bytes = record.serialize();
        let decoded = CdcRecord::deserialize(&bytes).unwrap();
        assert_eq!(decoded.table_name, "");
        assert!(decoded.key.is_empty());
        assert_eq!(decoded.new_value, Some(vec![]));
    }

    #[test]
    fn cdc_change_op_invalid_discriminant() {
        let err = ChangeOp::from_u8(255).unwrap_err();
        match err {
            crate::error::StorageError::FormatError { detail } => {
                assert!(detail.contains("invalid ChangeOp discriminant"));
            }
            other => panic!("expected StorageError::FormatError, got: {other:?}"),
        }
    }

    #[test]
    fn cdc_record_deserialize_empty_data() {
        let err = CdcRecord::deserialize(&[]).unwrap_err();
        match err {
            crate::error::StorageError::FormatError { detail } => {
                assert!(detail.contains("empty"));
            }
            other => panic!("expected StorageError::FormatError, got: {other:?}"),
        }
    }

    #[test]
    fn cdc_record_deserialize_invalid_op() {
        let record = CdcRecord {
            op: ChangeOp::Insert,
            table_name: String::from("t"),
            key: vec![1],
            new_value: None,
            old_value: None,
        };
        let mut bytes = record.serialize();
        // Corrupt the op byte
        bytes[0] = 99;
        let err = CdcRecord::deserialize(&bytes).unwrap_err();
        match err {
            crate::error::StorageError::FormatError { detail } => {
                assert!(detail.contains("invalid ChangeOp discriminant"));
            }
            other => panic!("expected StorageError::FormatError, got: {other:?}"),
        }
    }
}

#![no_main]

use arbitrary::Arbitrary;
use libfuzzer_sys::fuzz_target;
use redb::cdc::types::{CdcKey, CdcRecord};
use redb::{ChangeOp, Key, Value};

#[derive(Arbitrary, Debug)]
enum FuzzOp {
    /// Deserialize arbitrary bytes as a CDC record -- must never panic.
    DeserializeRecord { data: Vec<u8> },
    /// Serialize then deserialize a constructed record -- roundtrip.
    RoundtripRecord {
        op_byte: u8,
        table_name: String,
        key: Vec<u8>,
        has_new: bool,
        new_value: Vec<u8>,
        has_old: bool,
        old_value: Vec<u8>,
    },
    /// CdcKey Value trait roundtrip.
    CdcKeyRoundtrip {
        transaction_id: u64,
        sequence: u32,
    },
    /// CdcKey Key::compare ordering consistency.
    CdcKeyCompare {
        txn_a: u64,
        seq_a: u32,
        txn_b: u64,
        seq_b: u32,
    },
    /// ChangeOp try_from for all byte values.
    ChangeOpFromByte { byte: u8 },
}

fuzz_target!(|op: FuzzOp| {
    match op {
        FuzzOp::DeserializeRecord { data } => {
            // Must not panic on any input.
            let _ = CdcRecord::deserialize(&data);
        }

        FuzzOp::RoundtripRecord {
            op_byte,
            table_name,
            key,
            has_new,
            new_value,
            has_old,
            old_value,
        } => {
            let change_op = match op_byte % 3 {
                0 => ChangeOp::Insert,
                1 => ChangeOp::Update,
                _ => ChangeOp::Delete,
            };
            // Truncate table name to u16::MAX bytes (serialization limit).
            let table_name: String = table_name.chars().take(200).collect();
            let record = CdcRecord {
                op: change_op,
                table_name,
                key,
                new_value: if has_new { Some(new_value) } else { None },
                old_value: if has_old { Some(old_value) } else { None },
            };
            let bytes = record.serialize();
            let restored = CdcRecord::deserialize(&bytes)
                .expect("roundtrip deserialization must succeed");
            assert_eq!(restored.op, record.op);
            assert_eq!(restored.table_name, record.table_name);
            assert_eq!(restored.key, record.key);
            assert_eq!(restored.new_value, record.new_value);
            assert_eq!(restored.old_value, record.old_value);
        }

        FuzzOp::CdcKeyRoundtrip {
            transaction_id,
            sequence,
        } => {
            let key = CdcKey::new(transaction_id, sequence);
            let bytes = <CdcKey as Value>::as_bytes(&key);
            let restored = <CdcKey as Value>::from_bytes(&bytes);
            assert_eq!(restored.transaction_id, transaction_id);
            assert_eq!(restored.sequence, sequence);
        }

        FuzzOp::CdcKeyCompare {
            txn_a,
            seq_a,
            txn_b,
            seq_b,
        } => {
            let a = CdcKey::new(txn_a, seq_a);
            let b = CdcKey::new(txn_b, seq_b);
            let bytes_a = <CdcKey as Value>::as_bytes(&a);
            let bytes_b = <CdcKey as Value>::as_bytes(&b);
            // Key::compare must agree with Ord.
            let key_cmp = <CdcKey as Key>::compare(&bytes_a, &bytes_b);
            let ord_cmp = a.cmp(&b);
            assert_eq!(key_cmp, ord_cmp);
        }

        FuzzOp::ChangeOpFromByte { byte } => {
            // Valid discriminants are 0, 1, 2. All others must return Err.
            let result = CdcRecord::deserialize(&[byte]);
            // Single byte is too short for a full record -- always Err.
            assert!(result.is_err());
        }
    }
});
